SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token_ref_sync_i18n_seed) = 42);

START TRANSACTION;
-- 锁定翻译版本，避免与后台词条编辑并行时丢失缓存失效版本。
INSERT INTO token_ref_sync_i18n_guard (verified)
SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token.system_setting
  WHERE BINARY setting_key = BINARY 'i18n.translations.revision' AND revision >= 0) = 1);
SELECT revision INTO @token_ref_sync_i18n_revision_before FROM token.system_setting
WHERE BINARY setting_key = BINARY 'i18n.translations.revision' FOR UPDATE;
-- 拒绝仅大小写/排序规则等价的异常键，不能把它们当作准确命中的词条。
INSERT INTO token_ref_sync_i18n_guard (verified)
SELECT 1 WHERE EXISTS (SELECT 1 FROM token.translates t JOIN token_ref_sync_i18n_seed s
  ON t.type = s.template_type
  AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_general_ci = s.tkey COLLATE utf8mb4_general_ci
  AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_unicode_ci = s.lang COLLATE utf8mb4_unicode_ci
  WHERE NOT (BINARY t.tkey = BINARY s.tkey AND BINARY t.lang = BINARY s.lang));

INSERT INTO token.translates (tkey, lang, tvalue, type, prop, title, is_del, action_time)
SELECT s.tkey, s.lang, s.tvalue, s.template_type, 0, '充值归集与通知功能同步', 0, UTC_TIMESTAMP()
FROM token_ref_sync_i18n_seed s
WHERE NOT EXISTS (SELECT 1 FROM token.translates t
  WHERE t.type = s.template_type
    AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin = s.tkey
    AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_bin = s.lang);
SET @token_ref_sync_i18n_inserted = ROW_COUNT();
UPDATE token.translates t JOIN token_ref_sync_i18n_seed s
  ON t.type = s.template_type
  AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin = s.tkey
  AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_bin = s.lang
SET t.tvalue = s.tvalue, t.action_time = UTC_TIMESTAMP()
WHERE TRIM(COALESCE(t.tvalue, '')) = '';
SET @token_ref_sync_i18n_filled = ROW_COUNT();

INSERT INTO token_ref_sync_i18n_guard (verified)
SELECT 1 WHERE EXISTS (SELECT 1 FROM token_ref_sync_i18n_seed s LEFT JOIN token.translates t
  ON t.type = s.template_type
  AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin = s.tkey
  AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_bin = s.lang
  WHERE t.id IS NULL OR TRIM(COALESCE(t.tvalue, '')) = '');
SET @token_ref_sync_i18n_changed = @token_ref_sync_i18n_inserted + @token_ref_sync_i18n_filled;
UPDATE token.system_setting
SET setting_value = LOWER(UUID()), revision = revision + 1, updated_at = UTC_TIMESTAMP(6)
WHERE BINARY setting_key = BINARY 'i18n.translations.revision' AND @token_ref_sync_i18n_changed > 0;
SET @token_ref_sync_i18n_revision_changed = ROW_COUNT();
INSERT INTO token_ref_sync_i18n_guard (verified)
SELECT 1 WHERE NOT (@token_ref_sync_i18n_revision_changed = IF(@token_ref_sync_i18n_changed > 0, 1, 0));
INSERT INTO token_ref_sync_i18n_guard (verified)
SELECT 1 WHERE NOT ((SELECT revision FROM token.system_setting
  WHERE BINARY setting_key = BINARY 'i18n.translations.revision')
  = @token_ref_sync_i18n_revision_before + IF(@token_ref_sync_i18n_changed > 0, 1, 0));
COMMIT;

DROP TEMPORARY TABLE token_ref_sync_i18n_seed;
DROP TEMPORARY TABLE token_ref_sync_i18n_guard;
SET SESSION transaction_isolation = @token_ref_sync_i18n_old_isolation;
SELECT JSON_OBJECT('inserted', @token_ref_sync_i18n_inserted, 'filled', @token_ref_sync_i18n_filled,
  'revisionChanged', @token_ref_sync_i18n_revision_changed) AS token_ref_sync_i18n_result;
